$ErrorActionPreference='Stop';$Repo=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$Go=(Get-Command go -ErrorAction Stop).Source;$Root=Split-Path (Split-Path $Go -Parent) -Parent;$OR=$env:GOROOT;$OC=$env:GOCACHE;$OT=$env:GOTMPDIR;$C=Join-Path $env:TEMP ("up255c-cache-"+$PID);$T=Join-Path $env:TEMP ("up255c-tmp-"+$PID);New-Item -ItemType Directory -Force $C,$T|Out-Null;$env:GOROOT=$Root;$env:GOCACHE=$C;$env:GOTMPDIR=$T;Push-Location $Repo
try{go env -w GOFLAGS=-buildvcs=false;if($LASTEXITCODE){throw'UP255C_ENV'};go clean -cache -testcache;if($LASTEXITCODE){throw'UP255C_CLEAN'};go test ./unitary ./cmd/unitary-up255c-history-augmented-purity -count=1;if($LASTEXITCODE){throw'UP255C_FOCUSED'};go test ./... -count=1;if($LASTEXITCODE){throw'UP255C_FULL'};$P1=((go run ./cmd/unitary-up255c-history-augmented-purity)|Out-String).Trim();$P2=((go run ./cmd/unitary-up255c-history-augmented-purity)|Out-String).Trim();if($P1-cne$P2){throw'UP255C_NONDET'};$R=$P1|ConvertFrom-Json;if($R.schema-cne'wingless.up255c-history-augmented-purity.v1'-or [int]$R.paired_initial_states-ne64-or [int]$R.partitions.Count-ne3){throw'UP255C_DESIGN'};if($R.parent_classification-cne'FULL_NATIVE_STATE_NONSEPARABLE'-or [int]$R.partitions[0].mixed_groups-ne[int]$R.parent_mixed_groups){throw'UP255C_ANCHOR'};if(-not$R.diagnostic_only-or$R.intervention_changed-or$R.classifier_training_used-or$R.adaptive_feature_selection_used-or$R.live_activation){throw'UP255C_BOUNDARY'};Write-Host $P1;Write-Host "classification=$($R.classification) static_mixed=$($R.partitions[0].mixed_groups) current_mixed=$($R.partitions[1].mixed_groups) trajectory_mixed=$($R.partitions[2].mixed_groups)";Write-Host 'WINGLESS_UP385_HARNESS_PASS'}finally{Pop-Location;$env:GOROOT=$OR;$env:GOCACHE=$OC;$env:GOTMPDIR=$OT;Remove-Item -Recurse -Force $C,$T -ErrorAction SilentlyContinue}}
